"""Drift check between the registry, DEV folders and Drive project folders.

Plan: docs/inventory/2026-10-03-execution-plan.md (step 3). portfolio.json is the one list
of everything started; DEV and Drive are locations its rows point to. This module reports
where the three have drifted apart. Like slate.py it never writes anything, and a check it
cannot run (Drive not mounted) is reported, never passed as OK.
"""

from __future__ import annotations

import datetime as _dt
import os
import re
import subprocess
from pathlib import Path

SKIP = {"_ARCHIVE", "_DRIVE", "_to_delete", "docs", "graphify-out", "_INBOX"}
STAGE_DIRS = ("_ACTIVE", "_DONE", "_STALLED")
RETIRED = {"merged", "archived"}
# Last date a bulk job rewrote every repo (9/9 consolidation, 9/10-9/12 Windows merge).
# Commits on or before it say nothing about real work.
MACHINE_CUTOFF = _dt.date(2026, 9, 12)


def default_drive_root() -> Path | None:
    env = os.environ.get("PORTFOLIO_DRIVE_ROOT")
    candidates = [Path(env)] if env else []
    candidates.append(Path("G:/My Drive/00_Primary_Storage_Drive"))
    cloud = Path.home() / "Library/CloudStorage"
    if cloud.is_dir():
        candidates += sorted(cloud.glob("GoogleDrive-*/My Drive/00_Primary_Storage_Drive"))
    return next((c for c in candidates if c.is_dir()), None)


def git_last_commit(path: Path) -> str:
    try:
        out = subprocess.run(["git", "-C", str(path), "log", "-1", "--format=%cs"],
                             capture_output=True, text=True, timeout=20)
        return out.stdout.strip()
    except (OSError, subprocess.SubprocessError):
        return ""


def _token(name: str) -> str:
    name = re.sub(r"^\d{4}(-\d{2}-\d{2})?_", "", name)
    return re.split(r"[_\-\s]", name.lower())[0]


def _family_hint(folder: str, rows: list[dict]) -> str:
    tok = _token(folder)
    if len(tok) < 3:
        return ""
    kin = [r["name"] for r in rows if _token(r["name"]) == tok and r.get("status") not in RETIRED]
    return f"same family as {', '.join(kin[:3])}?" if kin else ""


def _is_link(path: Path) -> bool:
    # Compare against the resolved parent, not abspath: a parent under a symlinked root
    # (macOS temp dirs live under /var -> /private/var) would otherwise flag every child.
    return path.is_symlink() or os.path.realpath(path) != os.path.join(os.path.realpath(path.parent), path.name)


def _is_repo(path: Path) -> bool:
    return (path / ".git").exists()


def _is_stub(repo: Path) -> bool:
    """True when docs/STATUS.md has no real item under `## Next`.

    That section is what where-was-i.py shows each morning, so a STATUS with history
    but no next step still leaves Eric with nothing to start from.
    """
    f = repo / "docs" / "STATUS.md"
    if not f.exists():
        return True
    in_next = False
    for line in f.read_text(encoding="utf-8", errors="ignore").splitlines():
        if line.startswith("## "):
            in_next = line[3:].strip().lower().startswith("next")
        elif in_next and line.strip().lstrip("-*0123456789. ").strip():
            return False
    return True


def check(data: dict, dev_root: Path, drive_root: Path | None = None, *,
          since: _dt.date = MACHINE_CUTOFF, last_commit=git_last_commit) -> dict:
    rows = data.get("projects", [])
    problems: list[dict] = []

    def add(kind, name, detail=""):
        problems.append({"kind": kind, "name": name, "detail": detail})

    known_dev = {r.get("dev_folder") for r in rows if r.get("dev_folder")} | {r["name"] for r in rows}
    for d in sorted(p for p in dev_root.iterdir() if p.is_dir()):
        if d.name in SKIP or d.name.startswith("."):
            continue
        # Depth 2, the same limit KeystoneOS discovery uses: a group folder (Football/) or a
        # repo that holds repos (SpecialRequests/) has projects one level down.
        # Skipped: hidden folders, junctions/symlinks (LibraryProject/ZoteroInjestion points at
        # the real ZoteroInjestion on purpose), and anything inside a retired project.
        retired = {r.get("dev_folder") for r in rows if r.get("status") in RETIRED}
        # private_children: child repos are athlete-named, so they get no rows (portfolio.json
        # is pushed and published); the parent's own STATUS lists them instead.
        private = {r.get("dev_folder") for r in rows if r.get("private_children")}
        subs = [] if d.name in retired | private else sorted(
            c for c in d.iterdir()
            if c.is_dir() and not c.name.startswith(".") and not _is_link(c) and _is_repo(c))
        if d.name not in known_dev:
            add("unregistered_dev", d.name, _family_hint(d.name, rows))
        elif not _is_repo(d) and not subs:
            add("not_a_repo", d.name, "not on GitHub")
        for c in subs:
            rel = f"{d.name}/{c.name}"
            if rel not in known_dev:
                add("unregistered_dev", rel, _family_hint(c.name, rows))

    for r in rows:
        if r.get("status") in RETIRED:
            continue
        folder = r.get("dev_folder")
        if folder and not (dev_root / folder).is_dir():
            add("missing_dev", r["name"], folder)
        elif (folder and r.get("status") in ("active", "paused")    # finished work needs no Next
              and _is_repo(dev_root / folder) and _is_stub(dev_root / folder)):
            last = last_commit(dev_root / folder)
            try:
                touched = bool(last) and _dt.date.fromisoformat(last) > since
            except ValueError:
                touched = False
            if touched:
                add("stub_status", r["name"], f"worked on {last}, STATUS.md has no Next step")

    if drive_root is None or not drive_root.is_dir():
        add("drive_unreachable", "", "Drive checks skipped")
    else:
        known_drive = {r.get("drive_folder") for r in rows if r.get("drive_folder")}
        for stage in STAGE_DIRS:
            base = drive_root / "01_PROJECTS" / stage
            if not base.is_dir():
                continue
            for d in sorted(p for p in base.iterdir() if p.is_dir()):
                if f"01_PROJECTS/{stage}/{d.name}" not in known_drive:
                    add("unregistered_drive", f"{stage}/{d.name}", _family_hint(d.name, rows))
        for r in rows:
            folder = r.get("drive_folder")
            if folder and r.get("status") not in RETIRED and not (drive_root / folder).exists():
                add("missing_drive", r["name"], folder)

    return {"status": "DRIFT" if problems else "OK", "problems": problems,
            "rows": len(rows), "drive_root": str(drive_root) if drive_root else None}


LABELS = {
    "unregistered_dev": "DEV folder with no row",
    "unregistered_drive": "Drive project with no row",
    "missing_dev": "row points at a missing DEV folder",
    "missing_drive": "row points at a missing Drive folder",
    "stub_status": "no Next step in STATUS",
    "not_a_repo": "project folder is not a git repo",
    "drive_unreachable": "Drive not reachable",
}


def format_report(result: dict) -> str:
    probs = result["problems"]
    lines = [f"crosswalk: {result['status']} - {len(probs)} problem(s) across {result['rows']} rows"]
    for p in probs:
        bits = [LABELS.get(p["kind"], p["kind"])]
        if p["name"]:
            bits.append(p["name"])
        if p["detail"]:
            bits.append(f"({p['detail']})")
        lines.append("  " + " - ".join(bits[:2]) + (" " + bits[2] if len(bits) > 2 else ""))
    return "\n".join(lines)

