        k = self.kinds(self.run_check())
        self.assertIn(("missing_dev", "Gone"), k)
        self.assertNotIn(("missing_dev", "Retired"), k)

    def test_missing_drive_folder_is_reported(self):
        self.assertIn(("missing_drive", "NoDrive"), self.kinds(self.run_check()))

    def test_stub_status_flagged_only_when_repo_was_touched_since_the_cutoff(self):
        self.assertIn(("stub_status", "Stubby"), self.kinds(self.run_check()))
        quiet = self.run_check(last_commit=lambda p: "2026-09-10")
        self.assertNotIn(("stub_status", "Stubby"), self.kinds(quiet))

    def test_unreachable_drive_is_reported_never_ok(self):
        result = self.run_check(drive_root=None)
        self.assertIn(("drive_unreachable", ""), self.kinds(result))
        self.assertEqual(result["status"], "DRIFT")

    def test_clean_registry_is_ok(self):
