        self.data["projects"][0]["drive_folder"] = "01_PROJECTS/_ACTIVE/2026-01-01_Alpha"
        self.data["projects"] += [row("Orphan", dev_folder="", drive_folder="01_PROJECTS/_ACTIVE/2026-02-02_Orphan"),
                                  row("Old", dev_folder="", drive_folder="01_PROJECTS/_DONE/Old"),
                                  row("Stubby")]
        result = self.run_check(last_commit=lambda p: "2026-09-01")
        self.assertEqual(result["status"], "OK", result["problems"])

    def test_report_is_one_line_per_problem_under_a_summary(self):
